UPDATE `quest_template` SET `LogTitle` = '一块奇怪的废料', `LogDescription` = '把这块奇怪的废料交给叛军营或格罗姆高营地的回收工程师。', `QuestDescription` = '<这块废料还带着余温，散着机油味。一侧印着半刮花的风险投资公司序列号，下面有人潦草地写着「原型机——请勿拾取」。>$B$B工程师会知道这是什么。联盟在叛军营有一位，部落则在格罗姆高营地。', `QuestCompletionLog` = '把废料交给一位回收工程师。' WHERE `ID` <=> 176000 AND `QuestType` <=> 2 AND `QuestLevel` <=> 34 AND `MinLevel` <=> 30 AND `QuestSortID` <=> 33 AND `AllowableRaces` <=> 0 AND `RewardNextQuest` <=> 0 AND `RewardXPDifficulty` <=> 3 AND `RewardMoney` <=> 0 AND `StartItem` <=> 0 AND `Flags` <=> 8 AND `RewardItem1` <=> 0 AND `RewardAmount1` <=> 0 AND `LogTitle` <=> 'A Strange Piece of Scrap' AND `LogDescription` <=> 'Take the Strange Piece of Scrap to the salvage engineer at the Rebel Camp or at Grom''gol Base Camp.' AND `QuestDescription` <=> '<The scrap is still warm and smells of machine oil. A half-scratched Venture Co. serial number is stamped on one side, and someone has scrawled "PROTOTYPE - DO NOT LOOT" beneath it.>$B$BAn engineer would know what this is. The Alliance has one at the Rebel Camp, and the Horde one at Grom''gol Base Camp.' AND `AreaDescription` <=> '' AND `QuestCompletionLog` <=> 'Bring the scrap to a salvage engineer.' AND `RequiredItemId1` <=> 9707001 AND `RequiredItemId2` <=> 0 AND `RequiredItemId3` <=> 0 AND `RequiredItemCount1` <=> 1 AND `RequiredItemCount2` <=> 0 AND `RequiredItemCount3` <=> 0 AND `ItemDrop1` <=> 0 AND `ItemDropQuantity1` <=> 0;
UPDATE `quest_template` SET `LogTitle` = '一只地精的破烂', `LogDescription` = '为菲兹尔博尔特·齿轮哨从荆棘谷北部的风险投资公司带回 6 个回收的齿轮箱、从风险投资公司伐木机取下一个伐木机动力核心，再从风险投资公司营地取下一只易挥发燃料罐。', `QuestDescription` = '那个序列号是风险投资公司的存货，其余部分还在外面！这些地精把这片丛林砍伐掏空，打掉的机械比诺莫瑞根造过的还多。$B$B我可以用他们的边角料拼出一台像样的回收装置，但要精密就得有零件：从他们的工人身上弄六个完好的齿轮箱，从他们的一台伐木机上拆下动力核心，再弄一只他们堆在营地的易挥发燃料罐。最后那个请轻一点。', `QuestCompletionLog` = '回到菲兹尔博尔特·齿轮哨那里。' WHERE `ID` <=> 176001 AND `QuestType` <=> 2 AND `QuestLevel` <=> 35 AND `MinLevel` <=> 30 AND `QuestSortID` <=> 33 AND `AllowableRaces` <=> 1101 AND `RewardNextQuest` <=> 176002 AND `RewardXPDifficulty` <=> 5 AND `RewardMoney` <=> 2500 AND `StartItem` <=> 0 AND `Flags` <=> 8 AND `RewardItem1` <=> 0 AND `RewardAmount1` <=> 0 AND `LogTitle` <=> 'One Goblin''s Junk' AND `LogDescription` <=> 'Bring Fizzlebolt Gearwhistle 6 Salvaged Gearboxes from the Venture Co. in northern Stranglethorn, a Shredder Power Core from a Venture Co. Shredder and a Volatile Fuel Canister from the Venture Co. Base Camp.' AND `QuestDescription` <=> 'That serial number is Venture Co. stock, and the rest of it is still out there! The goblins strip this jungle for timber and ore, and they throw away more machinery than Gnomeregan ever built.$B$BI can assemble a proper salvage unit from their leftovers, but precision needs parts: six intact gearboxes from their workers, a power core out of one of their Shredders, and one of those volatile fuel canisters they stack at the Base Camp. Gently with that last one, please.' AND `AreaDescription` <=> '' AND `QuestCompletionLog` <=> 'Return to Fizzlebolt Gearwhistle.' AND `RequiredItemId1` <=> 9707002 AND `RequiredItemId2` <=> 9707003 AND `RequiredItemId3` <=> 9707004 AND `RequiredItemCount1` <=> 6 AND `RequiredItemCount2` <=> 1 AND `RequiredItemCount3` <=> 1 AND `ItemDrop1` <=> 0 AND `ItemDropQuantity1` <=> 0;
UPDATE `quest_template` SET `LogTitle` = '需要组装', `LogDescription` = '摧毁风险投资公司营地的失控拾取机器人原型机，把它的校准逻辑核心带给菲兹尔博尔特·齿轮哨。', `QuestDescription` = '齿轮、动力、燃料……就是没有脑子。我的逻辑核心至今还在按气味分拣铜币。$B$B风险投资公司自己造了个拾取原型机，然后失控了。它在他们的营地巡逻，凡是没钉牢的东西都往回收。它的逻辑核心校准得完美无缺。砸了那台机器，把核心给我带来。', `QuestCompletionLog` = '回到菲兹尔博尔特·齿轮哨那里。' WHERE `ID` <=> 176002 AND `QuestType` <=> 2 AND `QuestLevel` <=> 36 AND `MinLevel` <=> 30 AND `QuestSortID` <=> 33 AND `AllowableRaces` <=> 1101 AND `RewardNextQuest` <=> 176003 AND `RewardXPDifficulty` <=> 5 AND `RewardMoney` <=> 2500 AND `StartItem` <=> 0 AND `Flags` <=> 8 AND `RewardItem1` <=> 0 AND `RewardAmount1` <=> 0 AND `LogTitle` <=> 'Assembly Required' AND `LogDescription` <=> 'Destroy the Haywire Lootbot Prototype at the Venture Co. Base Camp and bring its Calibrated Logic Core to Fizzlebolt Gearwhistle.' AND `QuestDescription` <=> 'Gears, power, fuel... and still no brain. My logic core keeps sorting copper coins by smell.$B$BThe Venture Co. built a looting prototype of their own and lost control of it. It patrols their Base Camp, grabbing everything that isn''t nailed down. Its logic core is perfectly calibrated. Destroy the machine and bring me that core.' AND `AreaDescription` <=> '' AND `QuestCompletionLog` <=> 'Return to Fizzlebolt Gearwhistle.' AND `RequiredItemId1` <=> 9707005 AND `RequiredItemId2` <=> 0 AND `RequiredItemId3` <=> 0 AND `RequiredItemCount1` <=> 1 AND `RequiredItemCount2` <=> 0 AND `RequiredItemCount3` <=> 0 AND `ItemDrop1` <=> 0 AND `ItemDropQuantity1` <=> 0;
UPDATE `quest_template` SET `LogTitle` = '实地测试', `LogDescription` = '使用拾取机器人实地遥控器，让拾取机器人从你在荆棘谷击败的风险投资公司工人身上采集 8 份实地测试样本。', `QuestDescription` = '它成了！至少图纸上说它该成。$B$B拿着这个遥控器，在风险投资公司工人附近召唤拾取机器人。打倒他们，让拾取机器人在每个人身上采一份实地测试样本。八个样本应该够我拿到数据了。一定要待在附近：它还没学会害羞。', `QuestCompletionLog` = '回到菲兹尔博尔特·齿轮哨那里。' WHERE `ID` <=> 176003 AND `QuestType` <=> 2 AND `QuestLevel` <=> 37 AND `MinLevel` <=> 30 AND `QuestSortID` <=> 33 AND `AllowableRaces` <=> 1101 AND `RewardNextQuest` <=> 176004 AND `RewardXPDifficulty` <=> 5 AND `RewardMoney` <=> 2500 AND `StartItem` <=> 9707006 AND `Flags` <=> 8 AND `RewardItem1` <=> 0 AND `RewardAmount1` <=> 0 AND `LogTitle` <=> 'Field Testing' AND `LogDescription` <=> 'Use the Lootbot Field Remote, then let the Lootbot collect 8 Field Test Samples from Venture Co. workers you defeat in Stranglethorn.' AND `QuestDescription` <=> 'It works! At least, the schematics say it should.$B$BTake this remote and summon the Lootbot near the Venture Co. workers. Defeat them and let the Lootbot collect a field test sample from each one. Eight samples should give me enough data. Do stay close: it has not learned to be shy yet.' AND `AreaDescription` <=> '' AND `QuestCompletionLog` <=> 'Return to Fizzlebolt Gearwhistle.' AND `RequiredItemId1` <=> 9707007 AND `RequiredItemId2` <=> 0 AND `RequiredItemId3` <=> 0 AND `RequiredItemCount1` <=> 8 AND `RequiredItemCount2` <=> 0 AND `RequiredItemCount3` <=> 0 AND `ItemDrop1` <=> 9707006 AND `ItemDropQuantity1` <=> 1;
UPDATE `quest_template` SET `LogTitle` = '有照回收助手', `LogDescription` = '把回收许可证申请书交给藏宝海湾的雷维尔加兹男爵。', `QuestDescription` = '八个完美样本！它准备好了。$B$B有个问题：藏宝海湾拥有这片海岸的回收权，没有执照的拾取机器人只会变成雷维尔加兹男爵桌上的废铁。申请书我已经填好了。把它交给男爵，盖上他的印章，拾取机器人就是你的了。', `QuestCompletionLog` = '把申请书交给藏宝海湾的雷维尔加兹男爵。' WHERE `ID` <=> 176004 AND `QuestType` <=> 2 AND `QuestLevel` <=> 38 AND `MinLevel` <=> 30 AND `QuestSortID` <=> 33 AND `AllowableRaces` <=> 1101 AND `RewardNextQuest` <=> 0 AND `RewardXPDifficulty` <=> 5 AND `RewardMoney` <=> 0 AND `StartItem` <=> 9707008 AND `Flags` <=> 8 AND `RewardItem1` <=> 57000 AND `RewardAmount1` <=> 1 AND `LogTitle` <=> 'Licensed Salvage Assistant' AND `LogDescription` <=> 'Take the Salvage License Application to Baron Revilgaz in Booty Bay.' AND `QuestDescription` <=> 'Eight perfect samples! It''s ready.$B$BThere is one problem: Booty Bay owns the salvage rights along this coast, and an unlicensed Lootbot ends up as scrap on Baron Revilgaz''s desk. I filled in the application. Take it to the Baron, and once it has his stamp, the Lootbot is yours.' AND `AreaDescription` <=> '' AND `QuestCompletionLog` <=> 'Bring the application to Baron Revilgaz in Booty Bay.' AND `RequiredItemId1` <=> 9707008 AND `RequiredItemId2` <=> 0 AND `RequiredItemId3` <=> 0 AND `RequiredItemCount1` <=> 1 AND `RequiredItemCount2` <=> 0 AND `RequiredItemCount3` <=> 0 AND `ItemDrop1` <=> 0 AND `ItemDropQuantity1` <=> 0;
UPDATE `quest_template` SET `LogTitle` = '一只地精的破烂', `LogDescription` = '为格里兹克·拾荒者从荆棘谷北部的风险投资公司带回 6 个回收的齿轮箱、从风险投资公司伐木机取下一个伐木机动力核心，再从风险投资公司营地取下一只易挥发燃料罐。', `QuestDescription` = '风险投资公司的破烂！朋友，你知道那是什么吗？白送的货。那些风险投资公司的小子扔掉的利润，比科赞一年赚的还多。$B$B我的想法是这样：一个机械搭档，你干苦活，它捣东西。我需要从他们工人那儿弄到六个能用的齿轮箱，从他们的一台伐木机上拆下动力核心，再从他们营地弄一只燃料罐。那只别摇。', `QuestCompletionLog` = '回到格里兹克·拾荒者那里。' WHERE `ID` <=> 176011 AND `QuestType` <=> 2 AND `QuestLevel` <=> 35 AND `MinLevel` <=> 30 AND `QuestSortID` <=> 33 AND `AllowableRaces` <=> 690 AND `RewardNextQuest` <=> 176012 AND `RewardXPDifficulty` <=> 5 AND `RewardMoney` <=> 2500 AND `StartItem` <=> 0 AND `Flags` <=> 8 AND `RewardItem1` <=> 0 AND `RewardAmount1` <=> 0 AND `LogTitle` <=> 'One Goblin''s Junk' AND `LogDescription` <=> 'Bring Grizzik Scrapsnatch 6 Salvaged Gearboxes from the Venture Co. in northern Stranglethorn, a Shredder Power Core from a Venture Co. Shredder and a Volatile Fuel Canister from the Venture Co. Base Camp.' AND `QuestDescription` <=> 'Venture Co. junk! You know what that is, friend? Free inventory. Those Venture boys throw away more profit than Kezan makes in a year.$B$BHere''s the pitch: a mechanical partner that picks up loot while you do the hard part. I need six working gearboxes from their workers, a power core out of one of their Shredders, and a fuel canister from their Base Camp. Don''t shake that one.' AND `AreaDescription` <=> '' AND `QuestCompletionLog` <=> 'Return to Grizzik Scrapsnatch.' AND `RequiredItemId1` <=> 9707002 AND `RequiredItemId2` <=> 9707003 AND `RequiredItemId3` <=> 9707004 AND `RequiredItemCount1` <=> 6 AND `RequiredItemCount2` <=> 1 AND `RequiredItemCount3` <=> 1 AND `ItemDrop1` <=> 0 AND `ItemDropQuantity1` <=> 0;
UPDATE `quest_template` SET `LogTitle` = '需要组装', `LogDescription` = '摧毁风险投资公司营地的失控拾取机器人原型机，把它的校准逻辑核心带给格里兹克·拾荒者。', `QuestDescription` = '齿轮、动力、燃料：躯体做好了。贵的是脑子。$B$B风险投资公司自己造了个抢掠原型机，还把遥控器弄丢了，现在正把他们的营地搅得一团乱。它的逻辑核心是顶级的。砸了那东西，把核心给我带来，我们就能省下几个月的研究。', `QuestCompletionLog` = '回到格里兹克·拾荒者那里。' WHERE `ID` <=> 176012 AND `QuestType` <=> 2 AND `QuestLevel` <=> 36 AND `MinLevel` <=> 30 AND `QuestSortID` <=> 33 AND `AllowableRaces` <=> 690 AND `RewardNextQuest` <=> 176013 AND `RewardXPDifficulty` <=> 5 AND `RewardMoney` <=> 2500 AND `StartItem` <=> 0 AND `Flags` <=> 8 AND `RewardItem1` <=> 0 AND `RewardAmount1` <=> 0 AND `LogTitle` <=> 'Assembly Required' AND `LogDescription` <=> 'Destroy the Haywire Lootbot Prototype at the Venture Co. Base Camp and bring its Calibrated Logic Core to Grizzik Scrapsnatch.' AND `QuestDescription` <=> 'Gears, power, fuel: the body''s done. The brain''s the expensive part.$B$BThe Venture Co. built a loot-grabbing prototype of their own and lost the remote, now it''s tearing up their Base Camp. Its logic core is top quality. Smash the thing, bring me the core, and we save months of research.' AND `AreaDescription` <=> '' AND `QuestCompletionLog` <=> 'Return to Grizzik Scrapsnatch.' AND `RequiredItemId1` <=> 9707005 AND `RequiredItemId2` <=> 0 AND `RequiredItemId3` <=> 0 AND `RequiredItemCount1` <=> 1 AND `RequiredItemCount2` <=> 0 AND `RequiredItemCount3` <=> 0 AND `ItemDrop1` <=> 0 AND `ItemDropQuantity1` <=> 0;
UPDATE `quest_template` SET `LogTitle` = '实地测试', `LogDescription` = '使用拾取机器人实地遥控器，让拾取机器人从你在荆棘谷击败的风险投资公司工人身上采集 8 份实地测试样本。', `QuestDescription` = '任何伟大的产品上市前都要实地测试。$B$B拿着这个遥控器，在风险投资公司工人附近召唤原型机。你把他们打倒，它就从每个人身上采一份样本。八个样本足以说服任何投资人。别离太远：它还没搞清自己是给谁干活的。', `QuestCompletionLog` = '回到格里兹克·拾荒者那里。' WHERE `ID` <=> 176013 AND `QuestType` <=> 2 AND `QuestLevel` <=> 37 AND `MinLevel` <=> 30 AND `QuestSortID` <=> 33 AND `AllowableRaces` <=> 690 AND `RewardNextQuest` <=> 176014 AND `RewardXPDifficulty` <=> 5 AND `RewardMoney` <=> 2500 AND `StartItem` <=> 9707006 AND `Flags` <=> 8 AND `RewardItem1` <=> 0 AND `RewardAmount1` <=> 0 AND `LogTitle` <=> 'Field Testing' AND `LogDescription` <=> 'Use the Lootbot Field Remote, then let the Lootbot collect 8 Field Test Samples from Venture Co. workers you defeat in Stranglethorn.' AND `QuestDescription` <=> 'Every great product needs a field test before launch.$B$BTake this remote and summon the prototype near the Venture Co. workers. You knock them down, it picks up a sample from each one. Eight samples should convince any investor. Stay close: it hasn''t figured out who it works for yet.' AND `AreaDescription` <=> '' AND `QuestCompletionLog` <=> 'Return to Grizzik Scrapsnatch.' AND `RequiredItemId1` <=> 9707007 AND `RequiredItemId2` <=> 0 AND `RequiredItemId3` <=> 0 AND `RequiredItemCount1` <=> 8 AND `RequiredItemCount2` <=> 0 AND `RequiredItemCount3` <=> 0 AND `ItemDrop1` <=> 9707006 AND `ItemDropQuantity1` <=> 1;
UPDATE `quest_template` SET `LogTitle` = '有照回收助手', `LogDescription` = '把回收许可证申请书交给藏宝海湾的雷维尔加兹男爵。', `QuestDescription` = '八个样本！我们有产品了！$B$B一个小细节：藏宝海湾拥有这里的回收权，雷维尔加兹男爵什么都要抽一份。许可证申请书我已经填好了。把它交给藏宝海湾的男爵，拿到他的印章，拾取机器人就全归你了。', `QuestCompletionLog` = '把申请书交给藏宝海湾的雷维尔加兹男爵。' WHERE `ID` <=> 176014 AND `QuestType` <=> 2 AND `QuestLevel` <=> 38 AND `MinLevel` <=> 30 AND `QuestSortID` <=> 33 AND `AllowableRaces` <=> 690 AND `RewardNextQuest` <=> 0 AND `RewardXPDifficulty` <=> 5 AND `RewardMoney` <=> 0 AND `StartItem` <=> 9707008 AND `Flags` <=> 8 AND `RewardItem1` <=> 57000 AND `RewardAmount1` <=> 1 AND `LogTitle` <=> 'Licensed Salvage Assistant' AND `LogDescription` <=> 'Take the Salvage License Application to Baron Revilgaz in Booty Bay.' AND `QuestDescription` <=> 'Eight samples! We''ve got a product!$B$BOne small detail: Booty Bay owns the salvage rights here, and Baron Revilgaz takes his cut of everything. I filled in the license application. Take it to the Baron in Booty Bay, get his stamp, and the Lootbot is all yours.' AND `AreaDescription` <=> '' AND `QuestCompletionLog` <=> 'Bring the application to Baron Revilgaz in Booty Bay.' AND `RequiredItemId1` <=> 9707008 AND `RequiredItemId2` <=> 0 AND `RequiredItemId3` <=> 0 AND `RequiredItemCount1` <=> 1 AND `RequiredItemCount2` <=> 0 AND `RequiredItemCount3` <=> 0 AND `ItemDrop1` <=> 0 AND `ItemDropQuantity1` <=> 0;
UPDATE `quest_offer_reward` SET `RewardText` = '风险投资公司的序列号……还有「原型机」？那些地精在外头造东西。$B$B你在哪儿找到的？算了。重要的是它有可能变成什么。' WHERE `ID` <=> 176000 AND `RewardText` <=> 'A Venture Co. serial number... and "PROTOTYPE"? The goblins are building something out there.$B$BWhere did you find this? Never mind. It''s what it could become that matters.';
UPDATE `quest_offer_reward` SET `RewardText` = '全都拿到了，而且燃料罐居然没炸。太好了！现在我可以开始组装了。' WHERE `ID` <=> 176001 AND `RewardText` <=> 'All of it, and the canister didn''t even explode. Splendid! Now I can start the assembly.';
UPDATE `quest_offer_reward` SET `RewardText` = '漂亮的核心。看看这些焊点！我们的拾取机器人终于有脑子了。' WHERE `ID` <=> 176002 AND `RewardText` <=> 'A beautiful core. Look at those solder joints! Our Lootbot finally has a brain.';
UPDATE `quest_offer_reward` SET `RewardText` = '八个样本，每一个都分好类、贴好标签。原型机超出了所有预期！' WHERE `ID` <=> 176003 AND `RewardText` <=> 'Eight samples, each one sorted and labeled. The prototype exceeded every prediction!';
UPDATE `quest_offer_reward` SET `RewardText` = '<雷维尔加兲男爵逐行读完申请书，然后满意地盖上印章。>$B$B一台有照的回收助手，文书齐全。藏宝海湾拿到自己那份，你拿到你的拾取机器人。皆大欢喜的买卖。$B$B好好照顾它。我可不想在拍卖行见到它。' WHERE `ID` <=> 176004 AND `RewardText` <=> '<Baron Revilgaz reads every line of the application, then stamps it with obvious satisfaction.>$B$BA licensed salvage assistant, all paperwork in order. Booty Bay gets its cut, you get your Lootbot. Good business all around.$B$BTake care of it. I don''t want to see it at the auction house.';
UPDATE `quest_offer_reward` SET `RewardText` = '看看这么多货物！燃料罐居然没爆。这才叫好买卖。' WHERE `ID` <=> 176011 AND `RewardText` <=> 'Look at all this merchandise! The canister didn''t even blow up. That''s what I call a good deal.';
UPDATE `quest_offer_reward` SET `RewardText` = '这才叫顶级逻辑核心。研发的钱是风险投资公司出的，产品归我们。' WHERE `ID` <=> 176012 AND `RewardText` <=> 'Now that''s a premium logic core. The Venture Co. paid for the research and we get the product.';
UPDATE `quest_offer_reward` SET `RewardText` = '八个样本，零起诉讼！投资人一定会爱死这个。' WHERE `ID` <=> 176013 AND `RewardText` <=> 'Eight samples and zero lawsuits! Investors are going to love this.';
UPDATE `quest_offer_reward` SET `RewardText` = '<雷维尔加兲男爵逐行读完申请书，然后满意地盖上印章。>$B$B一台有照的回收助手，文书齐全。藏宝海湾拿到自己那份，你拿到你的拾取机器人。皆大欢喜的买卖。$B$B好好照顾它。我可不想在拍卖行见到它。' WHERE `ID` <=> 176014 AND `RewardText` <=> '<Baron Revilgaz reads every line of the application, then stamps it with obvious satisfaction.>$B$BA licensed salvage assistant, all paperwork in order. Booty Bay gets its cut, you get your Lootbot. Good business all around.$B$BTake care of it. I don''t want to see it at the auction house.';
UPDATE `quest_request_items` SET `CompletionText` = '你手上那是什么？' WHERE `ID` <=> 176000 AND `CompletionText` <=> 'What have you got there?';
UPDATE `quest_request_items` SET `CompletionText` = '你找到零件了吗？精密就是一切。' WHERE `ID` <=> 176001 AND `CompletionText` <=> 'Have you found the parts? Precision is everything.';
UPDATE `quest_request_items` SET `CompletionText` = '你从那台机器上拿到逻辑核心了吗？' WHERE `ID` <=> 176002 AND `CompletionText` <=> 'Did you get the logic core from that machine?';
UPDATE `quest_request_items` SET `CompletionText` = '实地测试进行得怎么样？拾取机器人在采集吗？' WHERE `ID` <=> 176003 AND `CompletionText` <=> 'How is the field test going? Is the Lootbot collecting?';
UPDATE `quest_request_items` SET `CompletionText` = '申请书？还是一个侏儒的？让我看看。' WHERE `ID` <=> 176004 AND `CompletionText` <=> 'An application? From a gnome? Let me see it.';
UPDATE `quest_request_items` SET `CompletionText` = '我的零件到手了吗？时间就是金钱，朋友。' WHERE `ID` <=> 176011 AND `CompletionText` <=> 'Got my parts? Time is money, friend.';
UPDATE `quest_request_items` SET `CompletionText` = '那台跑掉的机器还在到处乱转吗？' WHERE `ID` <=> 176012 AND `CompletionText` <=> 'Is that runaway machine still running around?';
UPDATE `quest_request_items` SET `CompletionText` = '到现在有多少样本了？' WHERE `ID` <=> 176013 AND `CompletionText` <=> 'How many samples so far?';
UPDATE `quest_request_items` SET `CompletionText` = '申请书？还是卡特尔的人？让我看看。' WHERE `ID` <=> 176014 AND `CompletionText` <=> 'An application? From one of the Cartel? Let me see it.';
UPDATE `npc_text` SET `text0_0` = '啊，迟早会有别人来，只是时间问题。$b$b别怕。我叫阿德拉津，邦桑迪的祭司。死亡之神亲自派我来铲除希尔埃克、丹巴拉和埃洛莎·无影的野心。' WHERE `ID` <=> 162933 AND `text0_0` <=> 'Ah, it be only a matter o\' time before someone else came.$b$bDo not fear. Me name be Adlazin, Priest of Bwonsamdi. Da Loa of Death himself sent me to cut down da dangerous ambitions of Hir\'eek, Dambala, and Elortha-no-Shadra.' AND `BroadcastTextID0` <=> 0 AND `lang0` <=> 0 AND `Probability0` <=> 1;
UPDATE `creature_template` SET `name` = '彼岸之蝠' WHERE `entry` <=> 163814 AND `name` <=> 'Bat of the Other Side' AND `minlevel` <=> 15 AND `maxlevel` <=> 15 AND `faction` <=> 35 AND `unit_class` <=> 1 AND `type` <=> 1 AND `flags_extra` <=> 128;
